import {concealAttitudeLabels} from './npc-presentation.js';
import {originPages} from './origin-runtime.js';
import {vehicleStats,vehicleArt} from './vehicle-runtime.js';
import {vehiclePanel,garagePanel} from './vehicle-ui.js';
import {battleSlots,bustRole,enemyTargetRegions,commandPage,BEAT_MS,IMPACT_MS} from './battle-presentation.js';
import {encounterCommands} from './encounter-commands.js';
import {automaticDecision,automaticStep,canContinueDriving,declineRest,alternateDriver,syncMessageContext,appendMessage} from './automatic-journey.js';
import {mountMessageScroll,stopMessageScroll,resetMessageScroll} from './message-scroll.js';
import {destinationAt,remainingKm} from './route-runtime.js';
import {tripDuration, journalEntry} from './journey-ui.js';
import {characterPanel,inventoryPanel,peoplePicker,inspectedPerson,comparisonCard} from './ui-panels.js';
import {equipmentPreview,itemBonuses} from './equipment-model.js';
import {mountWorld,captureVisual,animateResult,playBattleBeat,clearBattleBeat} from './world-view.js';
import {applyBattleFrame,transitionFor} from './motion-model.js';
import {sceneTransition,waitForBeat,reducedMotion,toggleMotion} from './cinematics.js';
import {enemyLayout,biomeAt,BIOMES} from './journey-view-model.js';
import {Game,ITEMS,MODS,learned,display,phase,phaseName} from './engine.js';
const root=document.getElementById('app'),KEY='eastward.save.v1';let data,g,panel=null,timer=null,automaticTimer=null,sound=false,travelStarted=0,travelLength=12000,selectedEnemy=null,pendingCommand=null,combatMenu='root',presentation=null,busy=false,playbackController=null,playbackLabel='',playbackStep=null,playbackPhase=null;
const ui={personId:null,slot:'全部',itemId:null,shopItemId:null,watchId:null,picker:null,feedback:'',scrollCompare:false,commandPage:0,commandKey:''};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(path,alt='',cls='')=>`<img src="assets/${esc(path)}" alt="${esc(alt)}" class="${cls}">`;
const btn=(label,action,args='',cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${action==='choicePage'?`aria-label="${esc(label)}"`:''} data-args="${esc(args)}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const nameOf=(kind,id)=>data.catalog[kind].find(x=>x.id===id)?.name||id;
const portrait=p=>data.assets.portraits[p.race];
const bar=(v,max,type='')=>`<div class="bar ${type}"><i style="width:${Math.max(0,Math.min(100,v/max*100))}%"></i></div>`;
function save(){if(g?.s){try{localStorage.setItem(KEY,JSON.stringify(g.s))}catch{g.s.notice='瀏覽器儲存空間不足，請匯出存檔。'}}}
function audio(){if(!sound)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),a=ctx.createGain();o.type='triangle';o.frequency.value=190;a.gain.setValueAtTime(.03,ctx.currentTime);a.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.1);o.connect(a);a.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12);o.onended=()=>ctx.close()}catch{}}
async function boot(){const files=['assets/manifest.json','data/npc-catalog.json','data/oracles.json','data/events.json','data/building-events.json','data/traits.json','assets/encounters.json'];const v=await Promise.all(files.map(f=>fetch(f+new URL(import.meta.url).search).then(r=>{if(!r.ok)throw Error(f);return r.json()})));data={assets:v[0],catalog:v[1],oracles:v[2],events:v[3],buildings:v[4],traits:v[5],encounters:v[6]};g=new Game(data);g.recordVisuals=true;render()}
function car(v,party,classes=''){const a=vehicleArt(data.assets,v);return `<div class="vehicle ${classes}">${a.windows.map((w,i)=>party[i]?`<img class="passenger" src="assets/${portrait(party[i])}" alt="${esc(display(party[i]))}" style="left:${w.x/160*100}%;top:${w.y/72*100}%;width:${Math.min(w.width,w.height)/160*100}%">`:'').join('')}${img(a.image,a.name,'body')}${v.mods?.filter(x=>x==='gun'||x==='lamp').slice(0,1).map(x=>img(data.assets.mods[x],MODS[x].name,'mod')).join('')}</div>`}
function worldPicture(id,cls=''){const a=data.assets.worlds[id];return `<svg class="painted-panorama ${cls}" viewBox="${a.rect.join(' ')}" role="img" aria-label="${esc(BIOMES.find(b=>b.id===id)?.name||id)} · 外星佔領區"><image href="assets/${a.image}" width="${a.size[0]}" height="${a.size[1]}"/></svg>`}
function intro(){let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY))}catch{}return `<div class="intro"><div class="eyebrow">A ROAD THROUGH THE AFTERMATH</div><h1>一路向東</h1><p>外星統治地球，已經十年。<br>你還有一輛車，和一個向東的理由。</p><div class="intro-scene">${worldPicture('city')}${img(data.assets.vehicles.sedan.image,'往東行駛的車','intro-car')}</div><p class="random-traveller">每段旅程，都由一位不同的旅人開始。<br>帶著他的身分、天賦與缺點，一路向東。</p><div class="actions">${btn('開始新的旅程','start','','primary')}${saved?btn(`繼續旅程 · 第 ${Math.floor(saved.minutes/1440)+1} 天`,'load'):''}</div><div class="footer-note">單人遊戲 · 自動保存在此瀏覽器<br><a href="art.html" target="_blank">像素圖鑑</a></div></div>`;}
function partyStrip(battle=false){const s=presentation||g.s,actor=battle&&!presentation?g.commandActor():null,allyTarget=pendingCommand?.allies,clickable=allyTarget||!battle,people=battleSlots(s.party);
 return `<div class="party-strip ${battle?'battle-party':'travel-party'}" aria-label="${battle?'我方隊員':'同行者狀態'}">${people.map((p,index)=>{if(!p)return `<div class="battle-slot empty-slot" data-slot="${index}" aria-label="空隊伍欄位 ${index+1}"><div class="member empty-member"></div></div>`;
 const order=s.battle?.orders?.[p.id],orderName={attack:'攻擊',defend:'防禦',medicine:'藥品',escape:'逃跑',psi:'超能力'}[order?.type],pose=battle&&presentation?bustRole(playbackStep,p.id):null;
 const poseText=pose==='attack'?'出手中':pose?(playbackPhase==='windup'?'迎擊':{hit:'受擊',evade:'閃避',guard:'擋下'}[pose]):'';
 const card=`<${clickable?'button':'div'} data-person="${p.id}" aria-label="${esc(display(p))}，生命 ${p.hp}/${p.maxHp}，體力 ${p.st}/${p.maxSt}，ESP ${p.esp}/${p.maxEsp}" title="${esc(display(p))}" class="member ${p.id===actor?.id?'active':''} ${p.hp<=0?'fallen':''} ${allyTarget?'ally-target':''}" ${clickable?`data-action="${allyTarget?'targetAlly':'openPerson'}" data-args="${p.id}" ${allyTarget&&p.hp<=0?'disabled':''}`:''}><div class="member-identity">${img(portrait(p),'')}<span><strong>${esc(p.name)}</strong><small>${p.hp<=0?'倒下':p.asleep?'睡眠中':p.id===s.driver&&!battle?(s.mode==='driving'?'駕駛中':'駕駛')+' · Lv. '+p.level:'Lv. '+p.level+' · '+nameOf('professions',p.profession)}</small></span></div><div class="member-vitals">${[['生命',p.hp,p.maxHp,'hp'],['體力',p.st,p.maxSt,'st'],['ESP',p.esp,p.maxEsp,'esp']].map(([name,v,max,k])=>`<div><span>${name}<b>${v}<small>/${max}</small></b></span>${bar(v,max,k)}</div>`).join('')}</div>${battle?`<span class="order-state">${poseText||(p.hp<=0?'倒下':p.asleep?'睡眠':orderName?'✓ '+orderName:p.id===actor?.id?'▸ 指令':'等待')}</span>`:''}</${clickable?'button':'div'}>`;
 return `<div class="battle-slot ${pose==='attack'?'acting':pose?'targeted':''}" data-slot="${index}" ${pose?`data-pose="${pose}" data-phase="${playbackPhase}"`:''}>${card}</div>`;
 }).join('')}</div>`;
}
function hud(){
 const s=presentation||g.s,v=vehicleStats(data.assets,s.vehicle),fuel=s.resources.fuel,reserve=s.resources.fuelReserve||0;
 const metrics=[['油箱',fuel+'/'+v.capacity,'fuel'],['車況',s.vehicle.hp+'/'+s.vehicle.maxHp,'condition'],['裝甲',v.armor,'armor']];
 return `<header class="vehicle-hud">${routeHeader()}<div class="vehicle-readouts">${metrics.map(([label,value,id])=>`<span class="vehicle-stat ${id}"><small>${label}</small><b>${value}</b></span>`).join('')}<span class="vehicle-stat velocity"><b id="journey-speed">0</b><small>km/h</small></span></div><div class="vehicle-meta"><span>${esc(v.name)} · ${s.party.length}/${Math.min(4,v.seats)} 席${reserve?' · 備用油 '+reserve:''}</span><span id="journey-time">第 ${Math.floor(s.minutes/1440)+1} 天 · ${phaseName(s.minutes)}</span></div></header>`;
}
function routeHeader(){const s=presentation||g.s,km=remainingKm(s.progress),destination=destinationAt(s);return `<div class="route-header" aria-label="旅程位置"><strong id="journey-place">${esc(biomeAt(s.progress,s.seed,s.route).name)}</strong><div class="destination-readout"><span>距離 ${esc(destination.name)}</span><span>還剩 <b id="journey-distance">${km.toLocaleString('en-US')}</b> 公里</span></div><div class="route-track" role="img" aria-label="距離樂園還剩 ${km} 公里"><i id="journey-progress" style="width:${100-km/10}%"></i></div></div>`;}
function enemyTargets(){const s=presentation||g.s;if(!s.battle)return '';const enemies=s.battle.enemies,regions=enemyTargetRegions(enemies,enemyLayout(enemies.length,enemies));return enemies.map((e,i)=>{const r=regions[i];return `<button class="world-target ${e.hp<=0?'defeated':''} ${selectedEnemy===e.id?'selected':''} ${pendingCommand&&!pendingCommand.allies?'await-target':''}" style="left:${r.left/384*100}%;width:${r.width/384*100}%;--caption-x:${r.caption/ r.width*100}%" data-enemy-id="${e.id}" ${e.hp<=0?'disabled aria-hidden="true"':''} data-action="targetEnemy" data-args="${e.id}" aria-label="${pendingCommand&&!pendingCommand.allies?'對':'鎖定'}${esc(e.name)}" aria-pressed="${selectedEnemy===e.id}"><span class="enemy-caption"><span>${esc(e.name)}</span><small>HP ${e.hp}/${e.maxHp}</small>${bar(e.hp,e.maxHp,'hp')}</span></button>`;}).join('');}
function scene(){const s=presentation||g.s,title=s.battle?(s.battle.finalBoss?'樂園前的決戰':s.battle.mode==='vehicle'?'公路追逐':'遭遇戰')+' · '+s.battle.round+' 回合':s.mode==='driving'?'向東行駛':s.current?.inside||s.frames?.at(-1)?.kind==='building'?(s.current?.place?.name||'建築內部'):(s.current?.place?.name||'公路旁');return `<section class="scene world-stage ${s.mode==='driving'?'driving':''} ${s.battle?'battle-stage':''}"><canvas id="world-canvas" width="384" height="240" role="img" aria-label="公路遊戲場景"></canvas><div class="scene-badge">${esc(title)}</div><span class="compass">${s.battle?'VS':'E →'}</span><div class="world-targets">${enemyTargets()}</div></section>`}

function messageWindow(){const s=presentation||g.s,decision=presentation?'wait':automaticDecision(g);let prompt='',actions='';
 if(decision==='rest'){const p=g.driver(),other=alternateDriver(g);prompt=`${display(p)}的體力只剩 ${p.st}。${canContinueDriving(g)?'要停車休息嗎？':'已經無法安全開車，需要休息或換人接手。'}`;actions=btn('停車休息','restBegin','','primary')+btn('再開一段','keepDriving','','',!canContinueDriving(g))+(other?btn(other.name+'接手','restSwap'): '');}
 if(decision==='restSetup'){const guard=g.s.party.find(p=>p.id===ui.watchId&&p.st>0&&p.hp>0);if(!guard)ui.watchId=null;prompt=guard?`${display(guard)}守夜，其他人睡眠四小時。`:'全員睡眠四小時。無人守夜；若遇襲，敵人會先攻。';actions=btn('守夜：'+(guard?.name||'無人')+' ▸','cycleWatch')+btn('開始睡眠','sleep','','primary')+btn('取消','restCancel');}
 if(decision==='stranded'){prompt=s.resources.fuel<=0?'油箱已空。需要尋找燃料，或換一輛能開的車。':'車輛已無法行駛。需要尋找修理物資或替代車輛。';actions=btn('到附近尋找出路','search','','primary');}
 if(decision==='vehicle'){prompt='附近找到了一輛可以使用的車。';actions=btn('查看車輛','panel','offer','primary')+btn('保留原車','passVehicle');}
 if(decision==='blocked'){prompt='車內座位不足，先整理同行隊伍。';actions=btn('整理隊伍','panel','party','primary');}
 const events=encounterCommands(g,display),commandKey=[s.mode,s.current?.instance,s.current?.event?.id,events.map(c=>c.action+':'+c.args).join(',')].join('|');if(ui.commandKey!==commandKey){ui.commandKey=commandKey;ui.commandPage=0;}
 let controls='',heading=s.battle?(presentation?'戰況':display(g.commandActor()||s.party[0])+' · 選擇指令'):s.mode==='driving'?'車內 · 沿途片刻':s.current?.place?.name||s.current?.event?.title||'旅途訊息';
 if(s.battle)controls=`<div class="message-commands battle-message-commands" aria-label="戰鬥指令">${presentation?btn('略過本輪動畫 ›','skipPlayback','','quiet'):combatBody()}</div>`;
 else if(actions)controls=`<div class="message-actions">${actions}</div>`;
 else if(events.length){const page=commandPage(events,ui.commandPage);controls=`<div class="message-commands" aria-label="事件選項"><div class="event-choice-grid">${page.items.map(c=>btn(c.label,c.action,c.args,c.style,c.disabled)).join('')}</div>${page.pages>1?`<div class="choice-pagination">${btn('‹ 上一頁','choicePage',page.page-1,'quiet',page.page===0)}<span>${page.page+1} / ${page.pages}</span>${btn('更多選項 ›','choicePage',page.page+1,'quiet',page.page===page.pages-1)}</div>`:''}</div>`;}
 let messages=presentation?[{id:0,title:playbackStep?.visual?.name||'戰況',text:playbackLabel||'準備行動…'}]:(s.messages||[]);
 const opening=s.mode==='prologue'?originPages(g)[s.prologue.step]:null;if(opening){heading='出發之前 · '+(s.prologue.step+1)+' / 3';messages=[{id:'origin-'+s.prologue.step,...opening,personId:s.protagonistId}];controls=`<div class="message-actions">${s.prologue.step?btn('前一頁','prologueBack','','quiet'):''}${btn(['那個向東的理由 ›','看看這次的座駕 ›','發動引擎'][s.prologue.step],'prologueNext','','primary')}</div>`;}
 return `<section class="message-window ${prompt?'has-prompt':''} ${controls?'has-commands':''}" aria-label="旅途訊息視窗"><div class="message-heading"><span>${esc(heading)}</span><small>往上看先前訊息</small></div><div class="message-scroll" role="log" aria-label="訊息與對話" aria-live="polite" tabindex="0">${messages.map(m=>{const p=s.party.find(p=>p.id===m.personId);return `<article class="message-line ${p?'has-person':''}" data-message-id="${m.id}">${p?img(portrait(p),''):''}<div><strong>${esc(m.title)}</strong>${p?`<small>${nameOf('races',p.race)} · ${nameOf('professions',p.profession)}</small>`:''}<p>${esc(concealAttitudeLabels(m.text))}</p></div></article>`;}).join('')}${prompt?`<p class="travel-prompt">${esc(prompt)}</p>`:''}</div>${controls}</section>`;
}

function scheduleAutomatic(){clearTimeout(automaticTimer);automaticTimer=null;if(!g.s||panel||presentation||busy||document.hidden)return;const decision=automaticDecision(g);if(!['drive','finish','resolveSearch'].includes(decision))return;
 const delay=decision==='drive'?1000:Math.min(6500,Math.max(2500,(g.s.notice?.length||0)*45));automaticTimer=setTimeout(async()=>{automaticTimer=null;if(panel||busy||document.hidden||automaticDecision(g)!==decision)return;const before=structuredClone(g.s);resetVisuals();try{automaticStep(g);await presentChange(before,decision);}catch(error){console.error(error);g.s.notice='行動暫停：'+error.message;render();}},delay);
}
function navigation(){const paths={party:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-2a6 6 0 0 1 12 0v2M16 5a4 4 0 0 1 0 7M17 15a5 5 0 0 1 5 5v1',bag:'M7 7V5a3 3 0 0 1 3-3h4a3 3 0 0 1 3 3v2M4 7h16v14H4ZM4 13h16M10 11v5h4v-5',vehicle:'M3 15l2-8h14l2 8v5h-3v-3H6v3H3ZM4 13h16M7 16h2m6 0h2',journal:'M4 3h12l4 4v14H4ZM8 8h5m-5 5h8m-8 4h6',menu:'M4 6h16M4 12h16M4 18h16'};return `<nav class="nav" aria-label="旅程選單">${[['party','隊伍'],['bag','背包'],['vehicle','車輛'],['journal','紀錄'],['menu','選單']].map(([id,label])=>`<button data-action="panel" data-args="${id}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]}"/></svg><span>${label}</span></button>`).join('')}</nav>`}
function combatBody(){const s=g.s,p=g.commandActor(),orders=Object.keys(s.battle.orders||{}),reserved=Object.values(s.battle.orders||{}).filter(o=>o.type==='medicine').length;let commands='';
 if(!p)commands=btn('等待敵方行動','combat','defend','primary');
 else if(pendingCommand)commands=`<p class="target-hint">${pendingCommand.allies?'點選上方隊員，選擇治療對象':'選擇目標，也可以直接點敵人'}</p>${pendingCommand.allies?'':`<div class="enemy-choices" aria-label="選擇攻擊目標">${s.battle.enemies.filter(e=>e.hp>0).map(e=>btn(e.name,'targetEnemy',e.id)).join('')}</div>`}${btn('返回指令','cancelCommand','','quiet')}`;
 else if(combatMenu==='psi')commands=`<div class="psi-list">${learned(p).map(pow=>btn(pow.name+' · '+pow.cost+' ESP','psi',pow.id,'',p.esp<pow.cost)).join('')}${btn('返回指令','cancelCommand','','quiet')}</div>`;
 else commands=`<div class="command-grid">${btn('⚔ 攻擊','combat','attack','primary')}${btn('✧ 超能力','psiMenu','','',s.battle.mode!=='character'||!learned(p).length)}${btn('✚ 藥品 '+(s.resources.medicine-reserved),'combat','medicine','',s.resources.medicine<=reserved)}${btn('◇ 防禦','combat','defend')}${btn('↗ 逃跑','combat','escape')}${btn('↶ 上一人','undoOrder','','quiet',!orders.length)}</div>`;
 return commands}
function panelHtml(){if(!panel)return '';const s=g.s;let title='',content='';if(panel==='party'){title='角色與裝備';content=characterPanel(g,data,ui);}
 if(panel?.startsWith('dismiss:')){const p=s.party.find(p=>p.id===panel.split(':')[1]);title='讓同伴離開';content=`<p>確定讓 ${esc(display(p))} 離開？他會帶走身上的裝備。將來也許還會在路上再度相遇。</p><div class="actions">${btn('讓他離開','dismiss',p.id,'danger')}${btn('留下','panel','party')}</div>`}
 if(panel==='bag'){title='裝備與背包';content=inventoryPanel(g,data,ui);}
 if(panel==='vehicle'){title='旅途中的座駕';content=vehiclePanel(g,data,{img,bar,display,esc,btn});}
 if(panel==='offer'){title='替代車輛';const o=s.offerVehicle;if(o){const v=data.assets.vehicles[o.model];content=`${img(v.image,v.name)}<h3>${v.name}</h3><p>${v.seats} 席 · 車況 ${o.hp}/${o.maxHp} · 剩餘汽油 ${o.fuel}</p><p class="event-text">換車時公共背包保留，舊車固定改裝不轉移。</p>${s.party.length>Math.min(4,v.seats)?`<p class="notice">需要先遣散 ${s.party.length-Math.min(4,v.seats)} 名同伴。</p>${btn('管理同伴','panel','party')}`:btn('換上這輛車','replace','','primary')}`}}
 if(panel==='menu'){title='旅程選單';content=`<div class="menu-summary"><span class="window-label">THE JOURNEY</span><h3>第 ${Math.floor(s.minutes/1440)+1} 天 · ${phaseName(s.minutes)}</h3><p>走過 ${s.progress} / 100 · ${s.stop} 次停靠</p></div><div class="actions system-actions">${btn('休息與守夜','panel','sleep','',!['ready','event'].includes(s.mode))}${btn('整理隊伍與裝備','panel','party')}${btn(reducedMotion()?'動畫：柔和':'動畫：完整','motion')}${btn('匯出旅程存檔','export')}</div><p class="panel-explanation">旅程會自動保存在此瀏覽器。</p>`;}
 if(panel==='journal'){title='旅途紀錄';const origin=s.party.find(p=>p.id===s.protagonistId)?.origin;content=(origin?`<details class="oral-archive"><summary>來時的路</summary><h3>${esc(origin.past.title)}</h3><p>${esc(origin.past.text)}</p><h3>${esc(origin.motive.title)}</h3><p>${esc(origin.motive.text)}</p></details>`:'')+`<div class="history-era"><span>外星統治 · 第十年</span><strong>${s.world.currentYear} 年</strong><small>佔領始於 ${s.world.year} 年 · ${esc(s.world.faction)}</small></div><details class="oral-archive"><summary>東方的傳聞 <span>${s.bossRumors?.length||0} 則</span></summary>${(s.bossRumors||[]).map(r=>`<article><small>${esc(r.speaker)}</small><p>${esc(r.text)}</p></article>`).join('')||'<p>還沒有聽過東方入口的消息。</p>'}</details><details class="oral-archive"><summary>旅人口述 <span>${s.oralHistory?.length||0} 則</span></summary><p class="tiny">記下旅人說過的話；傳聞與個人記憶未必等同完整史實。</p>${(s.oralHistory||[]).map(h=>`<article><small>佔領第 ${h.year} 年 · ${esc(h.speaker)} · ${h.attitude}</small><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p></article>`).join('')||'<p>還沒有聽到旅人的故事。</p>'}</details><div class="card"><h3>${s.world.archive}</h3><p class="tiny">這一局的世界，正在透過你的發現逐漸成形。</p>${s.history.map(t=>`<p class="event-text">${esc(t)}</p>`).join('')||'<p class="tiny">尚未取得歷史紀錄。</p>'}</div>${s.logs.map(journalEntry).filter(Boolean).map(l=>`<div class="log"><small>第 ${Math.floor(l.minutes/1440)+1} 天 · ${esc(l.title)}</small><p>${esc(l.text)}</p></div>`).join('')}`}
 if(panel==='shop'){title='交易與服務';const shop=s.current?.service;const items=[];if(shop==='npc_trade'){const npc=s.current.npc,stock=npc.stock||{fuel:1,medicine:1,item:1};if(stock.fuel)items.push(['10 點汽油 · '+g.price(3)+' 廢料','fuel:']);if(stock.medicine)items.push(['1 份藥品 · '+g.price(2)+' 廢料','medicine:']);const item=npc.tradeItem||'tools';if(stock.item)items.push([ITEMS[item].name+' · '+g.price(ITEMS[item].price)+' 廢料','item:'+item]);}if(['fuel_shop','general_shop'].includes(shop))items.push(['10 點汽油 · '+g.price(3)+' 廢料','fuel:']);if(['pharmacy','general_shop','clinic'].includes(shop))items.push(['1 份藥品 · '+g.price(2)+' 廢料','medicine:']);if(['general_shop','equipment_shop'].includes(shop))Object.entries(ITEMS).forEach(([id,it])=>items.push([it.name+' · '+g.price(it.price)+' 廢料','item:'+id]));if(shop==='clinic')items.push(['治療全隊 · 2 廢料','heal:']);if(shop==='hotel')items.push(['安全住宿 · 3 廢料','hotel:']);if(shop==='vehicle_shop')Object.entries(data.assets.vehicles).forEach(([id,v])=>items.push([v.name+' · '+g.price(10+v.seats*2)+' 廢料','vehicle:'+id]));content=`<p class="shop-wallet">持有 <b>${s.resources.scrap}</b> 廢料 · 交易者 ${esc(display(g.actor()))}</p>${items.some(([,a])=>a.startsWith('item:'))?peoplePicker(g,data,inspectedPerson(g,ui).id,'inspectPerson','裝備比較對象'):''}${ui.shopItemId?comparisonCard(g,data,ui,ui.shopItemId,{shop:true}):''}<div class="actions shop-items">${items.map(([l,a])=>a.startsWith('item:')?`<button class="shop-equipment" data-action="inspectShopItem" data-args="${a.split(':')[1]}"><strong>${esc(l)}</strong><small>${itemBonuses(a.split(':')[1])}</small><span>查看裝備比較 ›</span></button>`:btn(l,'buy',a)).join('')}</div>`;if(shop==='garage')content=garagePanel(g,{btn,img});}
 return `<div class="panel-back" data-panel="${esc(panel)}"><section class="panel game-panel" role="dialog" aria-modal="true" aria-labelledby="panel-title"><div class="panel-header"><div><small>EASTWARD / TRAVELLERS</small><h2 id="panel-title" tabindex="-1">${title}</h2></div>${btn('關閉','close','','quiet')}</div>${ui.feedback?`<div class="panel-feedback" role="status">${esc(ui.feedback)}</div>`:''}${content}</section></div>`}
function render(){if(!data)return;clearTimeout(automaticTimer);automaticTimer=null;stopMessageScroll();if(!g.s||g.s.mode!=='driving'){clearTimeout(timer);timer=null;}if(g.s&&!presentation)syncMessageContext(g,display);const oldDialog=root.querySelector('.panel-back'),oldPanel=oldDialog?.dataset.panel,oldScroll=oldDialog?.scrollTop||0;if(!g.s){root.className='';root.innerHTML=intro();restoreDialog(oldPanel,oldScroll);return;}const s=presentation||g.s;root.className='game-shell mode-'+s.mode+(s.mode==='combat'?' in-combat':'')+(presentation?' is-playing':'');
 if(s.mode!=='combat'){pendingCommand=null;combatMenu='root';}
 if(s.rosterReview&&s.party.length>4){root.innerHTML=`<div class="panel-back" data-panel="roster-review"><section class="panel game-panel" role="dialog" aria-modal="true" aria-labelledby="review-title"><div class="panel-header"><h2 id="review-title" tabindex="-1">調整同行隊伍</h2></div><p class="panel-explanation">隊伍上限為主角與 3 位同伴。舊存檔的角色與裝備都已保留，請選擇讓 ${s.party.length-4} 位同伴離隊，再繼續旅程。</p>${s.party.filter(p=>p.id!==s.protagonistId).map(p=>`<div class="legacy-companion">${img(portrait(p),'')}<div><strong>${esc(display(p))}</strong><small>${nameOf('races',p.race)} · ${nameOf('professions',p.profession)}</small></div>${btn('讓他離隊','reviewDismiss',p.id,'danger')}</div>`).join('')}<p class="panel-explanation">離隊者會帶著穿戴的裝備，將來仍可能再度相遇。公共背包保留。</p></section></div>`;restoreDialog(oldPanel,oldScroll);save();return;}
 if(s.mode==='ending'){root.innerHTML=`<div class="ending"><span class="label">END OF THE ROAD</span><h1>${s.end.win?'抵達'+esc(destinationAt(s).name):'旅程到此為止'}</h1>${worldPicture(s.end.win?'oasis':'salt')}<p>${esc(s.end.text)}</p><p class="muted">走到 ${s.progress}/100 · ${s.stop} 次停靠 · ${new Set(s.seen).size} 種發現</p><div class="actions">${btn('閱讀旅途紀錄','panel','journal')}${btn('再走一段不同的路','new','','primary')}${btn('匯出這段旅程','export')}</div></div>${panelHtml()}`;restoreDialog(oldPanel,oldScroll);save();return;}
 if(s.mode==='driving'&&!s.travel.preview)s.travel.preview=g.previewArrival();
 const previousCanvas=root.querySelector('#world-canvas');
 root.classList.add('portrait-layout');
 root.innerHTML=hud()+partyStrip(!!s.battle)+scene()+messageWindow()+navigation()+panelHtml();
 if(previousCanvas)root.querySelector('#world-canvas')?.replaceWith(previousCanvas);
 mountMessageScroll(root.querySelector('.message-scroll'),{prompt:!!root.querySelector('.travel-prompt'),transient:!!presentation});

 restoreDialog(oldPanel,oldScroll);save();if(s.mode==='driving'&&!timer){travelStarted=performance.now();travelLength=tripDuration(s);timer=setTimeout(()=>{timer=null;const before=structuredClone(g.s);resetVisuals();panel=null;g.arrive();presentChange(before,'arrive').catch(console.error)},travelLength);}mountWorld(document.getElementById('world-canvas'),s,data.assets,data.encounters,{duration:travelLength,travelStart:travelStarted,target:selectedEnemy,playback:!!presentation});
 if(presentation){root.querySelectorAll('button:not([data-action="skipPlayback"]),select').forEach(el=>el.disabled=true);}
 scheduleAutomatic();}
function restoreDialog(previous,scroll){const modal=root.querySelector('.panel-back');document.body.classList.toggle('has-dialog',!!modal);for(const el of root.children)el.inert=!!modal&&el!==modal;
 if(!modal)return;modal.scrollTop=modal.dataset.panel===previous?scroll:0;
 if(modal.dataset.panel!==previous)modal.querySelector('h2')?.focus({preventScroll:true});
 for(const track of modal.querySelectorAll('.people-picker')){const selected=track.querySelector('.selected');if(selected)track.scrollLeft=Math.max(0,selected.offsetLeft-track.offsetLeft-12);}
 if(ui.scrollTop){modal.scrollTop=0;ui.scrollTop=false;}
 if(ui.scrollCompare){ui.scrollCompare=false;modal.querySelector('#equipment-comparison')?.scrollIntoView({block:'nearest',behavior:'instant'});}
}
root.addEventListener('keydown',e=>{const modal=root.querySelector('[role="dialog"]');if(!modal)return;if(e.key==='Escape'){e.preventDefault();panel=null;ui.picker=null;render();return;}if(e.key==='Tab'){const focus=[...modal.querySelectorAll('button:not(:disabled),[tabindex="0"],summary')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&(document.activeElement===first||!focus.includes(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!focus.includes(document.activeElement))){e.preventDefault();first.focus();}}});
function resetVisuals(){g.visualSteps=[];g.visualStart=null;}
// During a beat the canvas and the skip button stay mounted through contact.
function refreshBattleBeat(phase){
 playbackPhase=phase;
 root.querySelector('.battle-party').outerHTML=partyStrip(true);
 const line=root.querySelector('.message-line');
 line.querySelector('strong').textContent=playbackStep.visual?.name||'戰況';
 line.querySelector('p').textContent=playbackLabel;
 const canvas=root.querySelector('#world-canvas');
 if(phase==='windup'){
  const targets=presentation.party.filter(p=>bustRole(playbackStep,p.id));
  const subjects=targets.map(p=>display(p)).join('、');
  canvas.setAttribute('aria-label',subjects?(playbackStep.side==='party'?subjects+'正在出手':playbackStep.name+'攻向'+subjects):playbackLabel);
 }else{
  root.querySelector('.world-targets').innerHTML=enemyTargets();
  root.querySelectorAll('.world-target').forEach(button=>button.disabled=true);
  if(playbackStep.effects.some(f=>f.side==='vehicle'))root.querySelector('.vehicle-hud').outerHTML=hud();
 }
}
async function presentChange(before,effectType){
 const steps=g.visualSteps||[],start=g.visualStart,transition=transitionFor(before,g.s),visualBefore=before?captureVisual(before):null;
 resetVisuals();save();
 if(!steps.length&&!transition){render();if(visualBefore&&g.s)animateResult(visualBefore,g.s,effectType);return;}
 busy=true;pendingCommand=null;combatMenu='root';panel=null;
 try{
  if(steps.length){
   presentation=start;playbackLabel='準備行動…';playbackController=new AbortController();
   await sceneTransition(transition,transition==='battle'?'遭遇戰':'走進建築',()=>render());
   for(const step of steps){
    if(playbackController.signal.aborted)break;
    playbackStep=step;playbackLabel=step.name+' · '+(step.kind==='stun'?'無法行動':step.visual?.name||'行動');
    const started=playBattleBeat(step);
    refreshBattleBeat('windup');
    await waitForBeat(Math.max(0,started+IMPACT_MS-performance.now()),playbackController.signal);
    if(playbackController.signal.aborted)break;
    applyBattleFrame(presentation,step.after);
    playbackLabel=step.name+'：'+step.label;
    refreshBattleBeat('contact');
    await waitForBeat(Math.max(0,started+BEAT_MS-performance.now()),playbackController.signal);
   }
  }else await sceneTransition(transition,transition==='battle'?'遭遇戰':transition==='leave'?'回到公路':g.s.current?.event.title||'走進建築',()=>render());
 }finally{presentation=null;playbackStep=null;playbackPhase=null;playbackController=null;clearBattleBeat();busy=false;render();}
}
function updateBattleControls(){
 stopMessageScroll();root.querySelector('.message-window').outerHTML=messageWindow();root.querySelector('.world-targets').innerHTML=enemyTargets();root.querySelector('.battle-party').outerHTML=partyStrip(true);mountMessageScroll(root.querySelector('.message-scroll'));
}
function browseCombat(action,args){if(!g.s?.battle||presentation||panel)return false;
 if(action==='combat'&&['attack','medicine'].includes(args))pendingCommand={type:args,allies:args==='medicine'};
 else if(action==='psiMenu')combatMenu='psi';
 else if(action==='cancelCommand'){pendingCommand=null;combatMenu='root';}
 else if(action==='targetEnemy'&&!pendingCommand){selectedEnemy=args;}
 else if(action==='psi'){const power=learned(g.commandActor()).find(p=>p.id===Number(args));if(!power||['shield','burst'].includes(power.type))return false;pendingCommand={type:'psi',power:args,allies:power.type==='heal'};}
 else return false;
 updateBattleControls();return true;
}
function commitCommand(target){if(!pendingCommand)return;const {allies,...command}=pendingCommand;if(g.combatRound({...command,target})){pendingCommand=null;combatMenu='root';}}
root.addEventListener('click',async e=>{if(e.target.classList.contains('panel-back')&&!busy){panel=null;ui.picker=null;render();return;}const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const {action:a,args:x}=b.dataset;if(a==='skipPlayback'){playbackController?.abort();return;}if(busy)return;if(browseCombat(a,x))return;if(g.s?.rosterReview&&g.s.party.length>4&&a!=='reviewDismiss')return;try{const before=g.s?structuredClone(g.s):null;resetVisuals();const effectType=pendingCommand?.type==='psi'||Object.values(g.s?.battle?.orders||{}).some(o=>o.type==='psi')?'psi':a==='combat'?x:a;audio();switch(a){case 'reviewDismiss':g.reviewParty(x);break;case 'motion':toggleMotion();break;case 'prologueNext':g.advancePrologue();resetMessageScroll();break;case 'prologueBack':if(g.s.mode==='prologue'&&g.s.prologue.step>0)g.s.prologue.step--;resetMessageScroll();break;case 'start':ui.personId=null;ui.feedback='';resetMessageScroll();g.startRandom();break;case 'load':{const s=JSON.parse(localStorage.getItem(KEY));if(s?.version!==1)throw Error('存檔版本不相容');resetMessageScroll();g=new Game(data,s);g.recordVisuals=true;break;}case 'new':resetMessageScroll();g.s=null;panel=null;break;case 'panel':if(x==='sleep'){g.s.journeyFlow.restSetup=true;ui.watchId=null;panel=null;break;}panel=x;ui.feedback='';ui.shopItemId=null;if(x==='bag'){ui.slot='全部';ui.itemId=null;}if(x==='sleep')ui.watchId=null;break;case 'close':panel=null;ui.feedback='';break;case 'depart':g.depart();break;case 'choicePage':ui.commandPage=Number(x);break;case 'cycleActor':{const people=g.alive().filter(p=>!p.asleep),i=people.findIndex(p=>p.id===g.actor()?.id);if(people.length)g.selectActor(people[(i+1)%people.length].id);break;}case 'choose':if(x==='__rest'){g.s.journeyFlow.restSetup=true;ui.watchId=null;}else g.choose(x);break;case 'explore':g.exploreBuilding();break;case 'finish':g.s.offerVehicle=null;g.s.strandedSearch?g.resolveSearch():g.finishEvent();break;case 'talk':g.talk();break;case 'trait':g.traitAction(x);break;case 'recruit':g.recruit();break;case 'attackNpc':g.beginCombat('character',null,g.s.current.npc);break;case 'driver':g.changeDriver(x);ui.feedback=g.s.notice;break;case 'heal':g.useMedicine(x);ui.feedback=g.s.notice;break;case 'dismissAsk':panel='dismiss:'+x;break;case 'dismiss':g.dismiss(x);panel='party';break;case 'openPerson':ui.personId=x;panel='party';ui.feedback='';break;case 'inspectPerson':ui.personId=x;ui.feedback='';break;case 'selectActor':g.selectActor(x);break;
case 'gearSlot':panel='bag';ui.slot=x;ui.itemId=null;ui.feedback='';break;case 'gearFilter':ui.slot=x;ui.itemId=null;ui.feedback='';break;
case 'inspectItem':ui.itemId=x;ui.feedback='';ui.scrollCompare=true;break;case 'inspectShopItem':ui.shopItemId=x;ui.feedback='';ui.scrollCompare=true;break;
case 'confirmEquip':{const p=inspectedPerson(g,ui),preview=equipmentPreview(g,p,x);if(preview?.owned&&!preview.same&&p.hp>0&&g.equip(p.id,x)){const changes=preview.stats.filter(v=>v.delta).map(v=>`${v.name} ${v.before} → ${v.after}`).join('、');ui.feedback=`${display(p)}已換上${ITEMS[x].name}。${changes}。${preview.previous?ITEMS[preview.previous].name+'已放回公共背包。':''}`;ui.itemId=null;ui.scrollTop=true;}else ui.feedback='目前無法更換這件裝備。';break;}
case 'watch':ui.watchId=x||null;break;
case 'buy':{const [kind,id]=x.split(':');if(!g.buy(kind,id))g.tell('物資不足、改裝格已滿，或目前不能使用這項服務。');ui.feedback=g.s.notice;if(kind==='mod')ui.scrollTop=true;if(kind==='item'&&ui.feedback==='交易完成。'){ui.feedback='已購買'+ITEMS[id].name+'，存放在公共背包。';ui.shopItemId=null;}if(g.s.offerVehicle)panel='offer';break;}case 'replace':g.replaceVehicle();panel=null;break;case 'restBegin':g.s.journeyFlow.restSetup=true;ui.watchId=null;break;case 'restCancel':g.s.journeyFlow.restSetup=false;break;case 'keepDriving':declineRest(g);break;case 'restSwap':{const p=alternateDriver(g);if(p)g.changeDriver(p.id);break;}case 'cycleWatch':{const ids=[null,...g.alive().filter(p=>p.st>0).map(p=>p.id)];ui.watchId=ids[(ids.indexOf(ui.watchId)+1)%ids.length];break;}case 'passVehicle':g.s.offerVehicle=null;break;case 'sleep':g.s.journeyFlow.restSetup=false;g.sleep(ui.watchId);panel=null;break;case 'search':g.searchStranded();break;case 'targetEnemy':selectedEnemy=x;if(pendingCommand&&!pendingCommand.allies)commitCommand(x);break;case 'targetAlly':if(pendingCommand?.allies)commitCommand(x);break;case 'cancelCommand':pendingCommand=null;combatMenu='root';break;case 'undoOrder':{const ids=Object.keys(g.s.battle.orders||{});if(ids.length)delete g.s.battle.orders[ids.at(-1)];pendingCommand=null;combatMenu='root';break;}case 'psiMenu':combatMenu='psi';break;case 'combat':if(['defend','escape'].includes(x)){g.combatRound({type:x});combatMenu='root';}else pendingCommand={type:x,allies:x==='medicine'};break;case 'psi':{const pow=learned(g.commandActor()).find(p=>p.id===Number(x));if(!pow)break;if(['shield','burst'].includes(pow.type)){g.combatRound({type:'psi',power:x});combatMenu='root';}else pendingCommand={type:'psi',power:x,allies:pow.type==='heal'};break;}case 'export':{const blob=new Blob([JSON.stringify(g.s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='一路向東-旅程存檔.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}await presentChange(before,effectType)}catch(err){console.error(err);if(g.s){g.s.notice='操作未完成：'+err.message;render()}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&g?.s)render();else {clearTimeout(automaticTimer);automaticTimer=null;}});
